// Stand-in for Electron inside nodejs-mobile: Riff's main-process modules register IPC handlers
// here, and android-main.js serves them to the WebView over HTTP.
const handlers = new Map();
let pendingPaths = [];

module.exports = {
  app: {
    getPath(name) {
      if (name === 'downloads') return process.env.RIFF_ANDROID_DOWNLOADS;
      if (name === 'userData') return process.env.RIFF_DATA_DIR;
      return process.env.HOME;
    },
    getVersion: () => process.env.RIFF_APP_VERSION || '',
    getLocale: () => process.env.LANG || 'en',
    isPackaged: true
  },
  ipcMain: {
    handle: (channel, fn) => handlers.set(channel, fn),
    on: (channel, fn) => handlers.set(channel, fn),
    removeHandler: (channel) => handlers.delete(channel)
  },
  // Android picks files natively first and passes the copies' paths along with the IPC call
  dialog: {
    showOpenDialog: async () => {
      const filePaths = pendingPaths;
      pendingPaths = [];
      return { canceled: filePaths.length === 0, filePaths };
    }
  },
  shell: {
    openPath: async () => '',
    openExternal: async () => {}
  },
  android: {
    handlers,
    setPendingPaths(paths) { pendingPaths = Array.isArray(paths) ? paths : []; }
  }
};
